<body>

    <div class="container">
        <div class="header">
            <h1>🎉 小美生日派對</h1>
            <p>邀請你一起來慶祝！</p>
        </div>

        <div class="content">
            <div class="countdown-box">
                <div class="countdown-title">距離派對還有</div>
                <div class="countdown-timer" id="countdown">計算中...</div>
            </div>

            <div class="info-card">
                <div class="info-item">
                    <span class="info-label">時間</span>
                    <span class="info-value">12 月 19 日（週六）下午 6 點</span>
                </div>
                <div class="info-item" style="margin-top: 12px;">
                    <span class="info-label">地點</span>
                    <span class="info-value">示範小館<br><small style="color:#666;">台北市示範路 1 號</small></span>
                </div>
            </div>

            <div class="rsvp-section">
                <div class="rsvp-title">你會來參加嗎？</div>
                <div class="btn-group">
                    <button class="btn btn-yes" onclick="openModal('我會去')">✨ 我會去</button>
                    <button class="btn btn-maybe" onclick="openModal('可能去')">🤔 可能去</button>
                    <button class="btn btn-no" onclick="openModal('去不了')">😢 去不了</button>
                </div>
            </div>

            <div class="guest-list">
                <h4>已回覆的名單 (<span id="guest-count">0</span>)</h4>
                <div class="guest-tags" id="guest-tags">
                    <span style="font-size: 12px; color: #999;">還沒有人回覆，快來搶頭香！</span>
                </div>
            </div>
        </div>
    </div>

    <div class="modal" id="rsvpModal">
        <div class="modal-content">
            <h3 id="modal-title">填寫您的名字</h3>
            <input type="text" id="guest-name" class="modal-input" placeholder="請輸入你的名字">
            <button class="modal-btn" onclick="submitRsvp()">送出回覆</button>
        </div>
    </div>

    <script>
        // 倒數計時
        function updateCountdown() {
            // 設定目標時間：當年度的 12 月 19 日 下午 6 點 (18:00)
            const now = new Date();
            let year = now.getFullYear();
            let targetDate = new Date(year, 11, 19, 18, 0, 0); // 11 代表 12月

            // 如果今年已經過了，就計算明年的
            if (now > targetDate) {
                targetDate = new Date(year + 1, 11, 19, 18, 0, 0);
            }

            const diff = targetDate - now;

            const days = Math.floor(diff / (1000 * 60 * 60 * 24));
            const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((diff % (1000 * 60)) / 1000);

            document.getElementById('countdown').innerText = 
                `${days} 天 ${hours} 小時 ${minutes} 分 ${seconds} 秒`;
        }

        setInterval(updateCountdown, 1000);
        updateCountdown();

        // 簡易回覆功能
        let selectedStatus = '';
        let guests = [
            { name: '小強', status: '我會去' },
            { name: '美美', status: '可能去' }
        ];

        function openModal(status) {
            selectedStatus = status;
            document.getElementById('modal-title').innerText = `你選擇了「${status}」`;
            document.getElementById('guest-name').value = '';
            document.getElementById('rsvpModal').style.display = 'flex';
        }

        function submitRsvp() {
            const nameInput = document.getElementById('guest-name');
            const name = nameInput.value.trim();

            if (!name) {
                alert('請輸入名字！');
                return;
            }

            guests.push({ name: name, status: selectedStatus });
            document.getElementById('rsvpModal').style.display = 'none';
            renderGuests();
        }

        function renderGuests() {
            const container = document.getElementById('guest-tags');
            const countSpan = document.getElementById('guest-count');

            countSpan.innerText = guests.length;

            if (guests.length === 0) {
                container.innerHTML = '<span style="font-size: 12px; color: #999;">還沒有人回覆，快來搶頭香！</span>';
                return;
            }

            container.innerHTML = '';
            guests.forEach(guest => {
                const tag = document.createElement('span');
                tag.className = 'tag ';
                if (guest.status === '我會去') tag.classList.add('tag-yes');
                else if (guest.status === '可能去') tag.classList.add('tag-maybe');
                else tag.classList.add('tag-no');

                tag.innerText = `${guest.name} (${guest.status})`
                container.appendChild(tag);
            });
        }

        // 初始化渲染預設名單
        renderGuests();

        // 點擊 Modal 以外區域關閉
        window.onclick = function(event) {
            const modal = document.getElementById('rsvpModal');
            if (event.target === modal) {
                modal.style.display = 'none';
            }
        }
    </script>
</body>
</html>
